cssRules.declarations:
display: inline-block;
  position: static;
  width: 1.65em;
  height: 1.65em;
  min-width: 1.65em;
  max-width: none;
  margin: -0.2em 0.1em;
  padding: 0;
  border: 0;
  background: none;
  box-shadow: none;
  object-fit: contain;
  vertical-align: -0.4em;
  pointer-events: none;
  user-select: none;
  flex: 0 0 auto;

display: inline-block;
  width: 1.5em;
  height: 1.5em;
  margin: 0;
  object-fit: contain;
  transform: translateY(1px);
  vertical-align: middle;
  pointer-events: none;

width: 28px;
  min-width: 28px;
  height: 28px;
  margin: 0;
  transform: translateY(1px);

position: absolute;
  z-index: 3;
  top: 70%;
  left: clamp(72px, 13%, calc(100% - 72px));
  pointer-events: none;
  transform: translate(-50%, -50%);
  animation: keyboard-hint-enter 110ms ease-out;

display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-bottom-color: rgba(255, 255, 255, 0.23);
  border-radius: 4px;
  background: #172024;
  color: #dce6e7;
  font-family: Consolas, monospace;
  font-size: 11px;
  transition: transform 75ms ease, border-color 75ms ease, background 75ms ease, color 75ms ease;

border-color: #8ff5e9;
  background: rgba(78, 223, 207, 0.34);
  box-shadow: 0 0 15px rgba(87, 230, 214, 0.56), inset 0 0 9px rgba(211, 255, 249, 0.18);
  color: #f2fffd;
  transform: translateY(1px) scale(0.94);
